{"file_text": "using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly over the dough.\n4. Tear mozzarella into pieces and distribute.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil." },
            new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated Pecorino and black pepper.\n4. Toss hot pasta with guanciale, then remove from heat.\n5. Stir in egg mixture quickly, tossing to coat without scrambling.\n6. Serve immediately with extra cheese and pepper." },
            new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for at least 1 hour.\n2. Grill or pan-sear chicken until charred.\n3. Sauté onion, garlic, and ginger until soft.\n4. Add tomatoes and simmer 15 minutes.\n5. Stir in cream and add the cooked chicken.\n6. Simmer 10 minutes and serve with rice or naan." },
            new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles\nTofu\nBean sprouts\nCarrots\nGreen onions\nPeanuts\nTamarind paste\nFish sauce\nLime\nChili flakes", Steps = "1. Soak rice noodles in warm water for 20 minutes.\n2. Press and cube tofu, then pan-fry until golden.\n3. Mix tamarind paste, fish sauce, and sugar for the sauce.\n4. Stir-fry carrots and green onions in a hot wok.\n5. Add drained noodles and sauce, toss to coat.\n6. Top with bean sprouts, crushed peanuts, and lime wedges." },
            new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet over medium-high heat.\n2. Add taco seasoning and water, simmer until thickened.\n3. Warm tortillas in a dry pan or microwave.\n4. Dice tomato and shred lettuce and cheese.\n5. Assemble tacos with meat and desired toppings.\n6. Serve with salsa and sour cream on the side." },
            new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nRed onion\nCilantro\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve avocados and remove pits.\n2. Mash avocado flesh to desired consistency.\n3. Finely dice onion, tomato, jalapeño, and cilantro.\n4. Mix all ingredients together with lime juice.\n5. Season with salt and minced garlic.\n6. Serve immediately with tortilla chips." },
            new Recipe { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla extract\nFlour\nBaking soda\nSalt\nChocolate chips", Steps = "1. Cream butter with both sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt in a separate bowl.\n4. Combine wet and dry ingredients.\n5. Fold in chocolate chips.\n6. Bake at 375°F (190°C) for 9-11 minutes." },
            new Recipe { Id = 8, Title = "Miso Soup", Category = "Asian", Ingredients = "Dashi stock\nWhite miso paste\nTofu\nWakame seaweed\nGreen onions", Steps = "1. Bring dashi stock to a gentle simmer.\n2. Rehydrate wakame seaweed in water.\n3. Cube soft tofu into small pieces.\n4. Remove pot from heat and whisk in miso paste.\n5. Add tofu and wakame to the broth.\n6. Serve garnished with sliced green onions." },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}
